CREATE TABLE IF NOT EXISTS garage_seed_events (
  key TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE garage_content ADD COLUMN navigation_label TEXT NOT NULL DEFAULT '';
ALTER TABLE garage_content ADD COLUMN navigation_group TEXT NOT NULL DEFAULT '';
ALTER TABLE garage_content ADD COLUMN symptoms_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE garage_content ADD COLUMN expectations_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE garage_content ADD COLUMN service_faqs_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE garage_content ADD COLUMN media_metadata_json TEXT NOT NULL DEFAULT '{"sourceUrl":"","license":"","attribution":"","representative":true}';

INSERT OR IGNORE INTO business_settings(id,settings_json,verified) VALUES
(1,'{"businessName":"Cumming Garage Door Service","phone":"(470) 555-0147","email":"service@cumminggaragedoor.example","serviceArea":"Cumming and Forsyth County (provisional)","hours":"Monday–Friday 8am–6pm; Saturday 9am–2pm; Sunday closed","coverage":"Cumming and Forsyth County (provisional)","urgentPolicy":"","theme":"industrial","serviceId":"garage-door-repair","emergencyEnabled":false,"heroImage":"/images/garage/hero-door-forward.jpg","galleryImages":["/images/garage/modern-white-home.jpg","/images/garage/classic-white-door.jpg","/images/garage/evening-home.jpg"],"productionApproved":false,"domainConfigured":false,"authConfigured":false,"claimVerification":{"businessName":{"status":"verified","isExample":false,"verifiedAt":null},"phone":{"status":"unverified","isExample":true,"verifiedAt":null},"email":{"status":"unverified","isExample":true,"verifiedAt":null},"hours":{"status":"unverified","isExample":true,"verifiedAt":null},"coverage":{"status":"unverified","isExample":true,"verifiedAt":null}},"trustProfile":{"hours":null,"ownerTeam":null,"yearsInBusiness":null,"brandsServiced":null,"paymentOptions":null,"financing":null,"licenseInsurance":null,"warranty":null}}',0);

UPDATE business_settings
SET settings_json=json_set(
  settings_json,
  '$.businessName','Cumming Garage Door Service',
  '$.phone','(470) 555-0147',
  '$.email','service@cumminggaragedoor.example',
  '$.serviceArea','Cumming and Forsyth County (provisional)',
  '$.hours','Monday–Friday 8am–6pm; Saturday 9am–2pm; Sunday closed',
  '$.coverage','Cumming and Forsyth County (provisional)',
  '$.urgentPolicy','',
  '$.emergencyEnabled',json('false'),
  '$.productionApproved',json('false'),
  '$.domainConfigured',json('false'),
  '$.authConfigured',json('false'),
  '$.claimVerification',json('{"businessName":{"status":"verified","isExample":false,"verifiedAt":null},"phone":{"status":"unverified","isExample":true,"verifiedAt":null},"email":{"status":"unverified","isExample":true,"verifiedAt":null},"hours":{"status":"unverified","isExample":true,"verifiedAt":null},"coverage":{"status":"unverified","isExample":true,"verifiedAt":null}}')
), verified=0, updated_at=CURRENT_TIMESTAMP
WHERE json_extract(settings_json,'$.businessName')='Summit Garage Door Co.'
  AND json_extract(settings_json,'$.phone')='(888) 555-0142'
  AND json_extract(settings_json,'$.email')='service@summitgaragedoor.com'
  AND verified=0;

UPDATE business_settings
SET settings_json=json_set(settings_json,'$.trustProfile.urgentPolicy',json('null'))
WHERE json_type(settings_json,'$.trustProfile.urgentPolicy') IS NULL;

UPDATE garage_content
SET navigation_label=CASE slug
  WHEN 'home' THEN 'Home' WHEN 'services' THEN 'Services'
  WHEN 'service-area' THEN 'Service Area' WHEN 'about' THEN 'About'
  WHEN 'blog' THEN 'Blog' WHEN 'contact' THEN 'Contact'
  WHEN 'gallery' THEN 'Gallery' WHEN 'faqs' THEN 'FAQs' ELSE navigation_label END,
  navigation_group=CASE WHEN kind='page' THEN 'main' ELSE navigation_group END
WHERE reviewed_seed=1;

UPDATE garage_content SET title='Garage Door Repair & Installation in Cumming, GA',navigation_label='Home',summary='Straightforward garage-door repair, installation, opener, and maintenance service for homes and businesses.',body='When a garage door stops moving, hangs unevenly, or no longer fits the way you use your property, Cumming Garage Door Service provides a clear path from inspection to repair or replacement. Tell us what you are seeing and request service; the team will review the details and confirm coverage, timing, and next steps.',verification_status='verified' WHERE id='page-home' AND reviewed_seed=1 AND title='Garage Door Trouble? Start Here.';
UPDATE garage_content SET title='Our Garage Door Services',navigation_label='Services',summary='Repair, replacement, opener, maintenance, and commercial garage-door services.',body='Choose the service that best matches the problem. You do not need to diagnose the door before requesting help; describe the movement, sound, visible damage, and door position, and the business will confirm the appropriate next step.',verification_status='verified' WHERE id='page-services' AND reviewed_seed=1 AND title='Garage Door Service Guides';
UPDATE garage_content SET title='Service Area',navigation_label='Service Area',summary='Provisional coverage centered on Cumming and Forsyth County.',body='Cumming and Forsyth County are the current provisional service-area examples. Enter the job address in a service request so coverage can be confirmed before relying on availability or travel timing.' WHERE id='page-service-area' AND reviewed_seed=1 AND title='Service-Area Planning';
UPDATE garage_content SET title='About Cumming Garage Door Service',navigation_label='About',summary='A focused local service experience built around careful assessment, clear options, and safe work.',body='Cumming Garage Door Service is designed to make a disruptive door problem easier to explain and resolve. Team history and trust claims appear only after the owner verifies each claim.',verification_status='verified' WHERE id='page-about' AND reviewed_seed=1 AND title='How to Evaluate a Garage Door Provider';
UPDATE garage_content SET title='Garage Door Advice',navigation_label='Blog',summary='Useful articles about door safety, operation, maintenance, and replacement planning.',verification_status='verified' WHERE id='page-blog' AND reviewed_seed=1 AND title='Garage Door Safety Library';
UPDATE garage_content SET title='Request Garage Door Service',navigation_label='Contact',summary='Send the property and door details the business needs to review your request.',body='Describe the problem, choose a preferred date and time, and include accurate contact and job-location details. Submitting a request does not confirm an appointment, price, coverage, or arrival time; the business must review and respond.',verification_status='verified' WHERE id='page-contact' AND reviewed_seed=1 AND title='Prepare a Service Request';
UPDATE garage_content SET title='Garage Door Style Inspiration',navigation_label='Gallery',summary='Explore representative door styles and planning ideas for your home or commercial property.',body='These licensed, representative images are design inspiration rather than a portfolio of completed Cumming Garage Door Service projects.',verification_status='verified' WHERE id='page-gallery' AND reviewed_seed=1 AND title='Project Planning Gallery';
UPDATE garage_content SET navigation_label='FAQs',verification_status='verified' WHERE id='page-faqs' AND reviewed_seed=1;

UPDATE garage_content SET slug='broken-spring-replacement',title='Broken Spring Replacement',summary='Replacement and system checks when a spring breaks or no longer balances the door.',service_code='broken-spring-replacement',navigation_group='services',symptoms_json='["A loud bang from the garage","A visible gap in a torsion spring","A door that feels unusually heavy","An opener that lifts only a few inches"]',expectations_json='["Door secured before inspection","Spring system and related hardware evaluated","Correct replacement options explained","Balance and travel tested before return to use"]',service_faqs_json='[{"question":"Can I open a door with a broken spring?","answer":"Do not force or lift an unusually heavy door. Keep it closed when safely possible and arrange professional service."},{"question":"Is spring replacement a DIY repair?","answer":"No. Springs, cables, and bottom brackets can cause severe injury when handled incorrectly."}]',verification_status='verified' WHERE id='service-spring' AND reviewed_seed=1 AND title='Broken Spring Safety Guide';
UPDATE garage_content SET slug='garage-door-opener-repair-installation',title='Garage Door Opener Repair & Installation',summary='Troubleshooting, repair, and installation for opener, control, and safety-sensor problems.',service_code='garage-door-opener-repair-installation',navigation_group='services',symptoms_json='["Remote, keypad, or wall control does not respond","Motor runs but the door does not move correctly","Door reverses or will not close","Excessive opener noise or intermittent operation"]',expectations_json='["Door and opener system assessed","Power, controls, drive, limits, and sensors assessed","Repair or compatible replacement options","Safety reversal and control testing"]',verification_status='verified' WHERE id='service-opener' AND reviewed_seed=1 AND title='Opener and Sensor Diagnostics';
UPDATE garage_content SET slug='cable-roller-off-track-repair',title='Cable, Roller & Off-Track Repair',summary='Stabilization and repair for frayed cables, failed rollers, damaged tracks, and crooked or hanging doors.',service_code='cable-roller-off-track-repair',navigation_group='services',symptoms_json='["Rollers outside the track","A crooked or hanging door","Frayed, loose, or displaced cables","Binding or scraping along the track"]',expectations_json='["Immediate attention to door stability","Inspection of tracks, rollers, cables, hinges, and brackets","Repair options based on the cause","Alignment and controlled-travel check"]',verification_status='verified' WHERE id='service-track' AND reviewed_seed=1 AND title='Off-Track Door Safety Guide';
UPDATE garage_content SET status='draft' WHERE id='service-hardware' AND reviewed_seed=1 AND title='Cables, Rollers, and Hinges';
UPDATE garage_content SET slug='new-garage-door-installation',title='New Garage Door Installation',summary='Measured replacement and installation for updated appearance, fit, insulation, and operation.',service_code='new-garage-door-installation',navigation_group='services',symptoms_json='["Severe panel or structural damage","Recurring failures or extensive corrosion","Poor fit, weather sealing, or insulation","A planned exterior update"]',expectations_json='["Opening and existing system measured","Style, material, insulation, and hardware options reviewed","Written scope confirmed","Final fit, balance, travel, and safety checks"]',verification_status='verified' WHERE id='service-replacement' AND reviewed_seed=1 AND title='Door Replacement Planning';
UPDATE garage_content SET slug='garage-door-maintenance-tune-ups',title='Garage Door Maintenance & Tune-Ups',summary='Inspection and adjustment intended to catch wear, noise, and movement problems early.',service_code='garage-door-maintenance-tune-ups',navigation_group='services',symptoms_json='["New squeaks, rattles, or vibration","Slower or less even travel","Worn weather seals or visible hardware wear","A door due for preventive inspection"]',expectations_json='["Visual and operational inspection","Hardware, balance, travel, and safety-system review","Appropriate adjustment and lubrication","Clear report of items needing repair"]',verification_status='verified' WHERE id='service-maintenance' AND reviewed_seed=1 AND title='Maintenance and Inspection Guide';

INSERT OR IGNORE INTO garage_content(id,kind,slug,aliases_json,title,navigation_label,navigation_group,summary,body,symptoms_json,expectations_json,service_faqs_json,image_url,image_alt,media_metadata_json,seo_title,seo_description,parent_id,sort_order,status,verification_status,featured,service_code,reviewed_seed)
VALUES
('service-repair','service','garage-door-repair','[]','Garage Door Repair','Garage Door Repair','services','Diagnosis and repair for doors that are stuck, noisy, uneven, damaged, or unreliable.','An assessment checks the complete balanced door system to identify the cause rather than masking a symptom.','["Door will not open or close","Grinding, popping, scraping, or vibration","Slow, uneven, or jerky movement","Loose or damaged hardware"]','["Whole-system inspection","Explanation of the fault and options","Approval before work begins","Operational and safety check"]','[{"question":"Do I need to know which part failed?","answer":"No. Describe what the door is doing and the assessment determines the cause."}]','/images/garage/hero-door-forward.jpg','Representative residential garage door','{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Tasso Mitsarakis on Pexels","representative":true}','Garage Door Repair','Garage door repair in Cumming, Georgia.','page-services',110,'published','verified',1,'garage-door-repair',1),
('service-commercial','service','commercial-garage-door-services','[]','Commercial Garage Door Services','Commercial Garage Door Services','services','Assessment, repair, maintenance, opener, and replacement planning for commercial overhead doors.','Commercial door service begins with the opening, equipment, duty cycle, access needs, safety systems, and operational impact.','["Commercial overhead door will not operate correctly","Damaged sections, tracks, rollers, cables, or controls","Recurring binding or unreliable travel","Planned maintenance or replacement"]','["Site and equipment details reviewed","Safety and operational priorities identified","Scope and scheduling confirmed","Return-to-service checks"]','[{"question":"Are all commercial door types covered?","answer":"Equipment scope is confirmed after the business reviews the door type, location, and issue."}]','/images/garage/gallery/garage-modern-building.jpg','Representative commercial overhead garage door','{"sourceUrl":"https://www.pexels.com/photo/industrial-brick-warehouse-with-metal-garage-door-28453365/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Airam Dato-on on Pexels","representative":true}','Commercial Garage Door Services','Commercial overhead door service information.','page-services',170,'published','verified',0,'commercial-garage-door-services',1),
('page-privacy','page','privacy','[]','Privacy Notice','Privacy','legal','How service-request and website information is handled.','A request collects name and contact details, job address and ZIP, issue, urgency, contact and scheduling preferences, description, and photos deliberately attached. Development uses PostgreSQL and app storage; production uses D1 and private R2 photos. Authorized staff and a configured verified HTTPS notification receiver can see request details. Maya full transcripts stay in temporary browser-session state; only service and a brief summary enter the request draft. Browser speech providers may process speech input. There is no automatic retention schedule. Use a verified contact or the request form to ask for access, correction, or removal. The owner must review notification receiver data practices before launch.','[]','[]','[]','/images/garage/hero-door-forward.jpg','Representative residential garage door','{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Tasso Mitsarakis on Pexels","representative":true}','Privacy Notice','Privacy information for service requests.','',90,'published','verified',0,'',1),
('page-request-terms','page','request-terms','[]','Service Request Terms','Request Terms','legal','What submitting a request does and does not confirm.','A service request asks the business to review the contact details, job address and ZIP, issue, preferences, and photos you provide. Authorized staff and a configured verified HTTPS notification receiver can see request details. Submission is not an appointment, dispatch, coverage decision, estimate, contract, price, or response-time promise.','[]','[]','[]','/images/garage/hero-door-forward.jpg','Representative residential garage door','{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Tasso Mitsarakis on Pexels","representative":true}','Service Request Terms','Terms for garage door service requests.','',100,'published','verified',0,'',1),
('location-cumming','location','cumming','[]','Garage Door Service in Cumming','','','Provisional coverage for Cumming, Georgia.','Cumming is an owner-authorized temporary coverage example. Submit the exact address for confirmation.','[]','[]','[]','/images/garage/hero-door-forward.jpg','Representative residential garage door','{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Tasso Mitsarakis on Pexels","representative":true}','Garage Door Service in Cumming','Provisional Cumming coverage.','page-service-area',210,'published','unverified',0,'',1),
('location-forsyth','location','forsyth-county','[]','Garage Door Service in Forsyth County','','','Provisional coverage across Forsyth County.','Forsyth County is an owner-authorized temporary coverage example subject to address confirmation.','[]','[]','[]','/images/garage/hero-door-forward.jpg','Representative residential garage door','{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free to use; https://www.pexels.com/license/","attribution":"Photo by Tasso Mitsarakis on Pexels","representative":true}','Garage Door Service in Forsyth County','Provisional Forsyth County coverage.','page-service-area',220,'published','unverified',0,'',1);

UPDATE garage_content SET status='draft' WHERE id IN ('location-atlanta','location-marietta','location-decatur','location-alpharetta') AND reviewed_seed=1;
UPDATE garage_content SET sort_order=120 WHERE id='service-spring' AND reviewed_seed=1 AND title='Broken Spring Replacement';
UPDATE garage_content SET sort_order=140 WHERE id='service-opener' AND reviewed_seed=1 AND title='Garage Door Opener Repair & Installation';
UPDATE garage_content SET media_metadata_json='{"sourceUrl":"https://www.pexels.com/photo/garage-door-in-building-7996765/","license":"Pexels License — free commercial use; source verified in PHOTO_SOURCES.md","attribution":"Tasso Mitsarakis / Pexels","representative":true}' WHERE reviewed_seed=1 AND image_url LIKE '%hero-door-forward%';
UPDATE garage_content SET media_metadata_json='{"sourceUrl":"https://www.pexels.com/photo/industrial-brick-warehouse-with-metal-garage-door-28453365/","license":"Pexels License — free commercial use; source verified in PHOTO_SOURCES.md","attribution":"Airam Dato-on / Pexels","representative":true}' WHERE reviewed_seed=1 AND (image_url LIKE '%service-commercial%' OR image_url LIKE '%garage-modern-building%');

INSERT OR IGNORE INTO garage_seed_events(key) VALUES ('garage-content-cumming-v2-schema');